<script setup lang="ts">
import { ref, computed, watch, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowUp, ArrowRight, EditPen, Document, CopyDocument, Download, Plus, Collection, ChatDotRound, Reading, Link, Close, FolderOpened } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useWorkspace } from '../store'
import { request, post, showError } from '../api'
import { terminal, safeLink, statusLabels } from '../types'
import type { Message, Evidence, Asset, Task, DocumentRow, AnswerResult } from '../types'
import MarkdownAnswer from '../components/MarkdownAnswer.vue'
import PdfViewer from '../components/PdfViewer.vue'
import TaskCard from '../components/TaskCard.vue'
import ProcessingTrace from '../components/ProcessingTrace.vue'
import { resolveCitation } from '../evidenceLocation'
const ws = useWorkspace(), route = useRoute(), router = useRouter()
const sessionId = computed(() => Number(route.query.session) || null)
const session = computed(() => ws.sessions.find(s => s.id === sessionId.value))
const messages = ref<Message[]>([]), assets = ref<Asset[]>([]), libraryDocs = ref<DocumentRow[]>([])
const loading = ref(false), sending = ref(false), draft = ref(''), error = ref(''), pendingQuestion = ref(''), activeAnswerId = ref(''), mode = ref('library')
const selectedDocIds = ref<number[] | null>(null), selectedAssets = ref<string[]>([]), evidence = ref<Evidence[]>([]), selectedEvidence = ref<Evidence | null>(null), sideTab = ref('original'), mobilePane = ref('chat')
const chatScroll = ref<HTMLElement>(), importDialog = ref(false), importAsset = ref<Asset | null>(null), targetLibrary = ref<number | null>(null), importing = ref(false)
let seenReadyAssets = new Set<string>(), refreshGeneration = 0, docsGeneration = 0
const library = computed(() => ws.libraries.find(l => l.id === ws.selectedLibrary))
const abstracts = computed(() => sessionId.value ? ws.sessionAbstracts[sessionId.value] || [] : [])
const readyDocs = computed(() => libraryDocs.value.filter(d => d.status === 'ready'))
const activeAnswer = computed(() => ws.tasks.find(t => t.id === activeAnswerId.value))
const working = computed(() => sending.value || !!activeAnswer.value && !terminal(activeAnswer.value.status))
const canAsk = computed(() => !!draft.value.trim() && !working.value && (mode.value === 'library' ? !!library.value : mode.value === 'external' ? !!(selectedAssets.value.length || abstracts.value.length) : !!library.value && !!(selectedAssets.value.length || abstracts.value.length)))
const pdfUrl = computed(() => { const meta = selectedEvidence.value?.metadata; if (!meta || meta.evidence_level === 'abstract' || meta.evidence_level === 'search_snippet') return; if (meta.asset_id || meta.resource_id) return `/api/assets/${encodeURIComponent(meta.asset_id || meta.resource_id)}/pdf`; if (Number(meta.doc_id) > 0) return `/api/documents/${Number(meta.doc_id)}/pdf` })
const pdfPage = ref(1)
const relatedTasks = computed(() => { const ids = String(route.query.tasks || '').split(','); return ws.tasks.filter(t => ids.includes(t.id) || t.kind === 'reading' && t.result?.session_id === sessionId.value).filter(t => t.status !== 'completed') })
const writableLibraries = computed(() => ws.libraries.filter(l => ['owner', 'editor'].includes(l.role)))
async function loadSession() {
  const token = ++refreshGeneration
  loading.value = true; error.value = ''; messages.value = []; assets.value = []; evidence.value = []; selectedEvidence.value = null; pendingQuestion.value = ''; activeAnswerId.value = ''; seenReadyAssets = new Set(); selectedAssets.value = []
  mode.value = ['library', 'external', 'mixed'].includes(String(route.query.mode)) ? String(route.query.mode) : 'library'; sideTab.value = route.query.tasks ? 'assets' : 'original'; activeAnswerId.value = String(route.query.answer || '')
  if (!sessionId.value) { loading.value = false; return }
  try { const [history, materials] = await Promise.all([request<Message[]>(`/sessions/${sessionId.value}/messages`), request<Asset[]>(`/sessions/${sessionId.value}/assets`)]); if (token !== refreshGeneration) return; messages.value = history; updateAssets(materials); const ownLibrary = ws.libraries.find(l => l.id === session.value?.group_id); if (ownLibrary) ws.selectedLibrary = ownLibrary.id; else if (!['library', 'external', 'mixed'].includes(String(route.query.mode)) && (materials.length || abstracts.value.length)) mode.value = 'external'; const last = [...history].reverse().find(m => m.result?.evidence?.length); if (last?.result?.evidence) { evidence.value = last.result.evidence; focusEvidence(evidence.value[0]!) }; mobilePane.value = 'chat'; await loadDocs(); await nextTick(); scrollBottom() } catch (e) { if (token === refreshGeneration) error.value = e instanceof Error ? e.message : '会话读取失败' } finally { if (token === refreshGeneration) loading.value = false }
}
function updateAssets(materials: Asset[]) {
  assets.value = materials
  if (!sessionId.value) return
  const saved = ws.sessionAssetScopes[sessionId.value]
  if (saved) { selectedAssets.value = saved.selected; seenReadyAssets = new Set(saved.seen) }
  for (const asset of materials) if (asset.status === 'ready' && !seenReadyAssets.has(asset.id)) { seenReadyAssets.add(asset.id); selectedAssets.value.push(asset.id) }
  selectedAssets.value = selectedAssets.value.filter(id => materials.some(a => a.id === id && a.status === 'ready'))
  ws.sessionAssetScopes[sessionId.value] = { selected: [...selectedAssets.value], seen: [...seenReadyAssets] }
}
async function loadDocs() { const token = ++docsGeneration, groupId = ws.selectedLibrary; selectedDocIds.value = null; libraryDocs.value = []; if (!groupId) return; try { const rows = await request<DocumentRow[]>(`/libraries/${groupId}/documents`); if (token !== docsGeneration || groupId !== ws.selectedLibrary) return; libraryDocs.value = rows; if (typeof route.query.docs === 'string') { const ids = route.query.docs.split(',').map(Number); selectedDocIds.value = libraryDocs.value.filter(d => d.status === 'ready' && ids.includes(d.id)).map(d => d.id) } } catch (e) { showError(e) } }
function changeSelection(value: unknown) { selectedDocIds.value = value === 'all' ? null : [] }
function toggleAsset(id: string, value: unknown) { selectedAssets.value = value ? [...selectedAssets.value, id] : selectedAssets.value.filter(selected => selected !== id); if (sessionId.value) ws.sessionAssetScopes[sessionId.value] = { selected: [...selectedAssets.value], seen: [...seenReadyAssets] } }
function scrollBottom() { chatScroll.value?.scrollTo({ top: chatScroll.value.scrollHeight, behavior: 'smooth' }) }
async function chooseSession(value: number) { router.push({ path: '/read', query: { session: value } }) }
async function rename() { if (!session.value) return; try { const result = await ElMessageBox.prompt('为这次研读起一个便于查找的名字。', '重命名研读', { inputValue: session.value.name, inputValidator: value => !!value.trim() && value.length <= 120 || '请输入 1–120 字的名称', confirmButtonText: '保存', cancelButtonText: '取消' }); await request(`/sessions/${session.value.id}`, { method: 'PATCH', body: JSON.stringify({ name: result.value.trim() }) }); session.value.name = result.value.trim() } catch (e) { if (e !== 'cancel' && e !== 'close') showError(e) } }
async function ask() {
  if (!canAsk.value) return
  sending.value = true; error.value = ''
  try {
    let id = sessionId.value
    if (!id) { const created = await ws.createSession(draft.value.slice(0, 36), mode.value === 'external' ? null : ws.selectedLibrary); id = created.id; await router.replace({ path: '/read', query: { session: id, mode: mode.value } }); await nextTick() }
    const question = draft.value.trim()
    const task = ws.track(await post<Task>('/answers', { session_id: id, question, mode: mode.value, group_id: mode.value === 'external' ? null : ws.selectedLibrary, selected_doc_ids: selectedDocIds.value, asset_ids: mode.value === 'library' ? [] : selectedAssets.value, abstracts: mode.value === 'library' ? [] : abstracts.value.map(a => ({ search_id: a.search_id, paper_id: a.paper_id })) }))
    activeAnswerId.value = task.id; pendingQuestion.value = question; draft.value = ''; router.replace({ path: '/read', query: { ...route.query, answer: task.id } }); await nextTick(); scrollBottom()
  } catch (e) { error.value = e instanceof Error ? e.message : '问答未完成' } finally { sending.value = false }
}
function focusEvidence(item: Evidence, page?: number) { selectedEvidence.value = item; pdfPage.value = page || Number(item.metadata.page_start || item.metadata.page) || 1; sideTab.value = 'original'; mobilePane.value = 'evidence' }
function citation(href: string, result?: AnswerResult) {
  const sources = result?.evidence || evidence.value
  evidence.value = sources
  const resolved = resolveCitation(href, sources, window.location.href)
  if (resolved) focusEvidence(resolved.evidence, resolved.page); else ElMessage.info('这条引用没有可打开的证据快照，可在来源列表中查看。')
}
function previewAsset(asset: Asset) { focusEvidence({ text: '', metadata: { asset_id: asset.id, resource_id: asset.id, paper_title: asset.paper.title, evidence_level: 'full_text', page: 1 } }) }
function startImport(asset: Asset) { importAsset.value = asset; targetLibrary.value = writableLibraries.value.find(l => l.kind === 'private')?.id || writableLibraries.value[0]?.id || null; importDialog.value = true }
async function confirmImport() { if (!importAsset.value || !targetLibrary.value) return; importing.value = true; try { ws.track(await post<Task>(`/reading-tasks/${importAsset.value.id}/imports`, { group_id: targetLibrary.value })); importDialog.value = false; ElMessage.success('已加入入库队列，会话资料仍可继续研读') } catch (e) { showError(e) } finally { importing.value = false } }
async function copy(text: string) { try { await navigator.clipboard.writeText(text); ElMessage.success('已复制回答') } catch { ElMessage.info('浏览器未允许复制，可选中回答文本后复制。') } }
function exportReading() { const content = `# ${session.value?.name || 'RefMind 研读'}\n\n` + messages.value.map(m => `## ${m.role === 'user' ? '问题' : '回答'}\n\n${m.content}`).join('\n\n'); const url = URL.createObjectURL(new Blob([content], { type: 'text/markdown;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'RefMind-研读记录.md'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function taskCompleted(event: Event) { const task = (event as CustomEvent<Task>).detail; if (!sessionId.value) return; try { if (task.kind === 'answer' && task.result?.session_id === sessionId.value && task.status === 'completed') { messages.value = await request<Message[]>(`/sessions/${sessionId.value}/messages`); if (task.id === activeAnswerId.value) { pendingQuestion.value = ''; activeAnswerId.value = '' }; const result = task.result as AnswerResult; evidence.value = result.evidence || []; if (evidence.value[0]) { const pane = mobilePane.value; focusEvidence(evidence.value[0]); mobilePane.value = pane }; await nextTick(); scrollBottom() } if (task.kind === 'reading' && (task.result?.session_id === sessionId.value || String(route.query.tasks || '').includes(task.id))) updateAssets(await request<Asset[]>(`/sessions/${sessionId.value}/assets`)) } catch (e) { showError(e) } }
watch(() => route.query.session, loadSession, { immediate: true })
watch(mode, value => { if (sessionId.value && String(route.query.mode || 'library') !== value) router.replace({ path: '/read', query: { ...route.query, mode: value } }) })
watch(() => ws.selectedLibrary, loadDocs, { immediate: true })
onMounted(() => window.addEventListener('refmind:task-complete', taskCompleted))
onBeforeUnmount(() => { refreshGeneration++; window.removeEventListener('refmind:task-complete', taskCompleted) })
</script>
<template><div class="reading-workspace"><header class="reading-heading"><div class="reading-title-group"><div class="eyebrow">RESEARCH READER</div><div class="reading-title"><h1>{{ session?.name || '新建一场有据可循的研读' }}</h1><el-button v-if="session" text circle aria-label="重命名研读" @click="rename"><el-icon><EditPen /></el-icon></el-button></div><p>围绕问题阅读，在原文中核验。</p></div><div class="reading-header-actions"><el-select v-if="ws.sessions.length" :model-value="sessionId" placeholder="选择研读会话" aria-label="选择研读会话" class="session-picker" @change="chooseSession"><el-option v-for="item in ws.sessions" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-button v-if="messages.length" text @click="exportReading" aria-label="导出研读记录"><el-icon><Download /></el-icon>导出记录</el-button></div></header><div class="mobile-pane-tabs"><button :class="{ active: mobilePane === 'chat' }" @click="mobilePane = 'chat'">问答</button><button :class="{ active: mobilePane === 'evidence' }" @click="mobilePane = 'evidence'">原文与证据</button></div><div :class="['reader-grid', `mobile-${mobilePane}`]"><section class="chat-panel"><div class="scope-toolbar"><el-select v-if="mode !== 'external'" v-model="ws.selectedLibrary" placeholder="选择文献库" class="reading-library" aria-label="本地文献库"><el-option v-for="item in ws.libraries" :key="item.id" :label="item.title" :value="item.id"/></el-select><el-popover v-if="mode !== 'external'" placement="bottom-start" :width="350" trigger="click"><template #reference><el-button text>{{ selectedDocIds === null ? '全部就绪文献' : `已选 ${selectedDocIds.length} 篇` }}<el-icon><ArrowRight /></el-icon></el-button></template><div class="scope-picker"><h4>本地证据范围</h4><el-radio-group :model-value="selectedDocIds === null ? 'all' : 'selected'" @change="changeSelection"><el-radio value="all">全部就绪文献</el-radio><el-radio value="selected">仅所选文献</el-radio></el-radio-group><el-checkbox-group v-if="selectedDocIds !== null" v-model="selectedDocIds"><el-checkbox v-for="document in readyDocs" :key="document.id" :value="document.id">{{ document.paper_title || document.filename }}</el-checkbox></el-checkbox-group><p v-if="!readyDocs.length" class="field-note">当前库尚无已就绪文献。</p></div></el-popover><span v-if="mode === 'external'" class="external-scope-label"><el-icon><Document/></el-icon>本轮仅使用选中的会话资料</span></div><div ref="chatScroll" class="chat-scroll" v-loading="loading"><div v-if="!messages.length && !pendingQuestion" class="reading-empty"><span class="reading-empty-icon"><el-icon><ChatDotRound /></el-icon></span><h2>从问题出发，向证据求解。</h2><p>选择文献范围后提出问题。<br>每条回答都可以回到原文验证。</p><div class="suggested-questions"><button @click="draft = '当前文献采用了哪些研究方法？各有什么适用条件？'">梳理研究方法与适用条件<el-icon><ArrowRight /></el-icon></button><button @click="draft = '当前文献有哪些明确说明的局限性？'">核对论文明确说明的局限性<el-icon><ArrowRight /></el-icon></button></div><router-link v-if="!ws.libraries.length" to="/library" class="text-action">创建文献库并上传论文<el-icon><ArrowRight /></el-icon></router-link></div><template v-for="message in messages" :key="message.id"><div v-if="message.role === 'user'" class="user-message"><span class="message-label">你的问题</span><p>{{ message.content }}</p></div><article v-else class="assistant-message"><div class="assistant-message-heading"><span class="assistant-symbol">R</span><strong>RefMind</strong><span v-if="message.result?.evidence?.length" class="answer-evidence-note">{{ message.result.evidence.length }} 条证据</span></div><MarkdownAnswer :text="message.content" @citation="href => citation(href, message.result)"/><el-alert v-if="message.result?.service_failed" title="本轮服务未完成，可保留问题后重试。" type="warning" :closable="false"/><el-collapse v-if="message.result?.warnings?.length" class="answer-diagnostics"><el-collapse-item title="本轮处理说明" :name="message.id"><p v-for="warning in message.result.warnings" :key="warning">{{ warning }}</p></el-collapse-item></el-collapse><ProcessingTrace :result="message.result" @evidence="focusEvidence"/><div class="message-actions"><el-button text size="small" @click="copy(message.content)"><el-icon><CopyDocument /></el-icon>复制</el-button><el-button v-if="message.result?.evidence?.length" text size="small" @click="evidence = message.result.evidence; sideTab = 'evidence'; mobilePane = 'evidence'">查看全部证据</el-button></div></article></template><div v-if="pendingQuestion" class="user-message"><span class="message-label">你的问题</span><p>{{ pendingQuestion }}</p></div><TaskCard v-if="activeAnswer" :task="activeAnswer"/><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/></div><div class="composer-area"><div class="mode-picker" role="group" aria-label="本轮证据模式"><button v-for="item in [{ value: 'library', label: '本地文献' }, { value: 'external', label: '会话资料' }, { value: 'mixed', label: '混合研读' }]" :key="item.value" :class="{ active: mode === item.value }" :aria-pressed="mode === item.value" @click="mode = item.value">{{ item.label }}</button></div><div v-if="mode !== 'library'" class="selected-materials"><span v-for="choice in abstracts" :key="choice.paper_id" class="material-chip abstract" :title="choice.title">摘要 · {{ choice.title }}<button aria-label="移除此摘要" @click="ws.sessionAbstracts[sessionId!] = abstracts.filter(a => a.paper_id !== choice.paper_id)"><el-icon><Close/></el-icon></button></span><span v-if="selectedAssets.length" class="material-chip">{{ selectedAssets.length }} 篇已就绪全文</span><span v-if="!selectedAssets.length && !abstracts.length" class="field-note">先在文献发现选择摘要，或等待全文任务完成。</span></div><form class="question-composer" @submit.prevent="ask"><textarea v-model="draft" aria-label="科研问题" placeholder="向文献提问，关键结论可回到原文核验…" maxlength="8000" rows="2" @keydown.enter.exact.prevent="ask"/><div class="composer-bottom"><span><span class="tiny-dot"></span>{{ mode === 'library' ? '仅在所选本地范围检索' : mode === 'external' ? '仅使用本会话选中的资料' : '本地文献 + 选中会话资料' }}</span><el-button class="send-button" native-type="submit" type="primary" :disabled="!canAsk" :loading="working" aria-label="发送问题"><el-icon><ArrowUp/></el-icon></el-button></div></form><p class="composer-footnote">Enter 发送 · Shift + Enter 换行 · 摘要与全文证据始终分别标明</p></div></section>
<aside class="evidence-panel"><div class="evidence-tabs"><button :class="{ active: sideTab === 'original' }" @click="sideTab = 'original'">原文阅读</button><button :class="{ active: sideTab === 'evidence' }" @click="sideTab = 'evidence'">证据<span>{{ evidence.length }}</span></button><button :class="{ active: sideTab === 'assets' }" @click="sideTab = 'assets'">会话资料<span>{{ assets.length }}</span></button></div><template v-if="sideTab === 'original'"><div v-if="selectedEvidence?.metadata.evidence_level === 'abstract'" class="abstract-evidence"><span class="evidence-badge abstract">摘要证据 · 未读取全文</span><h3>{{ selectedEvidence.metadata.paper_title }}</h3><p>{{ selectedEvidence.text }}</p><a v-if="safeLink(selectedEvidence.metadata.external_url)" :href="safeLink(selectedEvidence.metadata.external_url)" target="_blank" rel="noopener noreferrer" class="text-action">查看原始学术来源<el-icon><ArrowRight/></el-icon></a></div><PdfViewer v-else :url="pdfUrl" :title="selectedEvidence?.metadata.paper_title" :page="pdfPage" :evidence="selectedEvidence" @page="value => pdfPage = value"/><div v-if="selectedEvidence?.text && pdfUrl" class="evidence-excerpt"><strong>当前证据摘录</strong><p>{{ selectedEvidence.text }}</p></div></template><div v-else-if="sideTab === 'evidence'" class="evidence-list"><div v-if="!evidence.length" class="side-empty"><el-icon><Document/></el-icon><h3>证据将在这里汇集</h3><p>回答完成后，点击引用或查看证据清单。</p></div><button v-for="(item, index) in evidence" :key="index" class="evidence-card" @click="focusEvidence(item)"><div><span class="evidence-number">{{ index + 1 }}</span><span :class="['evidence-badge', item.metadata.evidence_level === 'abstract' ? 'abstract' : 'fulltext']">{{ item.metadata.evidence_level === 'abstract' ? '摘要' : '全文片段' }}</span><span class="evidence-page">{{ item.metadata.page_start || item.metadata.page ? `第 ${item.metadata.page_start || item.metadata.page} 页` : '无 PDF 页码' }}</span></div><h4>{{ item.metadata.paper_title || item.metadata.filename }}</h4><p>{{ item.text }}</p><span class="text-action">查看对应来源<el-icon><ArrowRight/></el-icon></span></button></div><div v-else class="session-assets"><div class="section-intro"><h3>本次研读的会话资料</h3><p>仅你可见，尚未自动加入正式文献库。临时原文保留 {{ ws.config?.temporary_retention_days || 7 }} 天。</p></div><TaskCard v-for="task in relatedTasks" :key="task.id" :task="task"/><div v-if="!assets.length && !relatedTasks.length" class="side-empty"><el-icon><FolderOpened/></el-icon><h3>尚未添加会话全文</h3><p>从文献发现选文后，获取公开全文开始研读。</p><el-button @click="router.push('/discover')">前往文献发现</el-button></div><article v-for="asset in assets" :key="asset.id" class="asset-card"><div class="asset-heading"><el-checkbox :model-value="selectedAssets.includes(asset.id)" :disabled="asset.status !== 'ready'" :aria-label="`选用 ${asset.paper.title}`" @change="toggleAsset(asset.id, $event)"/><h4>{{ asset.paper.title }}</h4></div><div class="asset-meta"><el-tag size="small" :type="asset.status === 'ready' ? 'success' : 'info'" effect="plain">{{ statusLabels[asset.status] || asset.status }}</el-tag><span>{{ asset.version || '版本未知' }}</span><span v-if="asset.coverage">{{ asset.coverage.parsed_pages?.length || 0 }}/{{ asset.coverage.total_pages }} 页已解析</span></div><div class="asset-actions"><el-button v-if="asset.status !== 'expired'" text size="small" @click="previewAsset(asset)">查看原文</el-button><el-button v-if="asset.status === 'ready'" text size="small" @click="startImport(asset)"><el-icon><Collection/></el-icon>保存到文献库</el-button></div></article></div></aside></div><el-dialog v-model="importDialog" title="保存到正式文献库" width="460px"><p class="dialog-description">{{ importAsset?.paper.title }}</p><el-select v-model="targetLibrary" placeholder="选择有写入权限的目标库" style="width: 100%"><el-option v-for="item in writableLibraries" :key="item.id" :label="`${item.title} · ${item.kind === 'shared' ? '共享库' : '私有库'}`" :value="item.id"/></el-select><p class="field-note">正式入库成功后将保留独立文档，会话资料仍可继续使用。</p><router-link v-if="!writableLibraries.length" to="/library" @click="importDialog = false" class="text-action">先创建文献库</router-link><template #footer><el-button @click="importDialog = false">取消</el-button><el-button type="primary" :disabled="!targetLibrary" :loading="importing" @click="confirmImport">加入入库队列</el-button></template></el-dialog></div></template>
